INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'lx-law-2019', id, '2019-05-16', 1, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-law-2019', 'en', 'Law of 16 May 2019 establishes the B2G e-invoicing framework', 'Luxembourg transposes EU Directive 2014/55/EU into national law, requiring public-sector suppliers to be able to send structured e-invoices. The Law of 13 December 2021 later amends it to fix the phased rollout dates by company size.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'lx-b2g', id, '2023-03-18', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2g', 'en', 'B2G e-invoicing mandate fully in force', 'Luxembourg''s phased B2G e-invoicing rollout completed: all economic operators, including small and newly established businesses, must now issue Peppol BIS Billing 3.0 / EN 16931 e-invoices to Luxembourg public sector bodies.', '["Confirm your Peppol Access Point (or guichet.lu''s manual upload option) is set up for every public contract you supply", "Structured EN 16931 invoices are required for all public procurement — no threshold applies"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'lx-b2b-receipt', id, '2028-01-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-receipt', 'en', 'Proposed: B2B e-invoice receipt becomes mandatory', 'Under the draft law approved by Luxembourg''s Council of Government on 17 July 2026, all businesses would be required to be able to receive structured e-invoices for domestic B2B transactions over a Peppol four-corner network, ahead of the issuance obligation.', '["Track the bill through Parliament — this is still a draft law, not yet enacted", "Confirm your invoicing/ERP system can already receive Peppol BIS Billing 3.0 invoices"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'lx-b2b-issue-large', id, '2028-07-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-large', 'en', 'Proposed: B2B e-invoice issuance for large & medium businesses', 'Large and medium-sized businesses would be required to issue, not just receive, structured domestic B2B e-invoices over Peppol — six months after the receipt obligation takes effect for everyone.', '["Larger suppliers: begin Peppol Access Point onboarding well ahead of this date", "Confirm current company-size classification, since it determines which deadline applies"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'lx-b2b-issue-all', id, '2029-01-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('lx-b2b-issue-all', 'en', 'Proposed: B2B e-invoice issuance becomes universal', 'The remaining businesses, including SMEs, would be required to issue structured domestic B2B e-invoices, completing the phased rollout announced alongside the EU''s VAT in the Digital Age (ViDA) reforms.', '["SMEs: this is the deadline that applies to you, 18 months after the receipt obligation begins", "No domestic real-time VAT reporting is planned alongside this — Luxembourg is staying with the Peppol interoperability model, not a clearance system"]');
